const prisma = new PrismaClient();

function enumValue<T extends Record<string, any>>(obj: T, key: string): T[keyof T] {
  return obj[key] ?? Object.values(obj)[0];
}

async function main() {
  const categoryCache = new Map<string, any>();
  const subcategoryCache = new Map<string, any>();
  let processed = 0;

  for (const item of questions) {
    let category = categoryCache.get(item.categoryName);

    if (!category) {
      category = await prisma.category.upsert({
        where: {
          slug: item.categoryName
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, "-")
            .replace(/(^-|-$)/g, ""),
        },
        update: {
          name: item.categoryName,
          group: item.categoryGroup,
        },
        create: {
          name: item.categoryName,
          slug: item.categoryName
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, "-")
            .replace(/(^-|-$)/g, ""),
          group: item.categoryGroup,
          description: `${item.categoryName} interview questions.`,
        },
      });
      categoryCache.set(item.categoryName, category);
    }

    let subcategoryId: string | null = null;

    if (item.subcategoryName) {
      const subKey = `${item.categoryName}:${item.subcategoryName}`;
      let sub = subcategoryCache.get(subKey);

      if (!sub) {
        const subSlug =
          item.source === 2 && item.companySlug
            ? `${item.companySlug}-${item.subcategoryName
                .toLowerCase()
                .replace(/[^a-z0-9]+/g, "-")}`
            : item.categoryName
                .toLowerCase()
                .replace(/[^a-z0-9]+/g, "-");

        sub = await prisma.subcategory.upsert({
          where: {
            categoryId_slug: {
              categoryId: category.id,
              slug: subSlug,
            },
          },
          update: { name: item.subcategoryName },
          create: {
            name: item.subcategoryName,
            slug: subSlug,
            categoryId: category.id,
          },
        });
        subcategoryCache.set(subKey, sub);
      }

      subcategoryId = sub.id;
    }

    await prisma.interviewQuestion.upsert({
      where: { slug: item.slug },
      update: {
        question: item.question,
        categoryId: category.id,
        subcategoryId,
        experienceLevel: enumValue(ExperienceLevel, item.experienceLevel),
        difficulty: enumValue(Difficulty, item.difficulty),
        interviewType: enumValue(InterviewType, item.interviewType),
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        ...(item.seoTitle ? { seoTitle: item.seoTitle } : {}),
        ...(item.seoDescription ? { seoDescription: item.seoDescription } : {}),
        isPublished: true,
      },
      create: {
        question: item.question,
        slug: item.slug,
        categoryId: category.id,
        subcategoryId,
        experienceLevel: enumValue(ExperienceLevel, item.experienceLevel),
        difficulty: enumValue(Difficulty, item.difficulty),
        interviewType: enumValue(InterviewType, item.interviewType),
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        ...(item.seoTitle ? { seoTitle: item.seoTitle } : {}),
        ...(item.seoDescription ? { seoDescription: item.seoDescription } : {}),
        isPublished: true,
      },
    });

    processed += 1;
    if (processed % 100 === 0 || processed === questions.length) {
      console.log(`Progress: ${processed}/${questions.length}`);
    }
  }

  console.log(`SUCCESS: Seeded ${questions.length} interview questions.`);
}

main()
  .catch(error => {
    console.error("Chunk seed failed:", error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
